// Let's write a function to simulate a ship request
function shipProduct(id, qty) {
  const conn = new Database('/home/user/inventory-app/data/inventory.db');
  try {
    const executeTx = conn.transaction((prodId, quantity) => {
      const product = conn.prepare('SELECT id FROM products WHERE id = ?').get(prodId);
      if (!product) throw new Error('Product not found');

      const currentQty = conn.prepare('SELECT COALESCE(SUM(delta), 0) as qty FROM stock_movements WHERE product_id = ?').get(prodId).qty;
      if (currentQty < quantity) {
        throw new Error(`Insufficient stock. Current: ${currentQty}, requested: ${quantity}`);
      }

      conn.prepare('INSERT INTO stock_movements (product_id, delta, reason) VALUES (?, ?, ?)').run(prodId, -quantity, 'ship');
      return `Successfully shipped ${quantity} units`;
    });

    return executeTx.immediate(id, qty);
  } catch (err) {
    return `Failed: ${err.message}`;
  } finally {
    conn.close();
  }
}

// Let's run them "concurrently" using Promise.all
async function run() {
  console.log('Running two concurrent ship requests of 6 units each...');
  const results = await Promise.all([
    Promise.resolve().then(() => shipProduct(3, 6)),
    Promise.resolve().then(() => shipProduct(3, 6))
  ]);
  console.log('Results:', results);

  const finalSum = db.prepare('SELECT COALESCE(SUM(delta), 0) as qty FROM stock_movements WHERE product_id = 3').get().qty;
  console.log('Final stock:', finalSum);
}

